import{_ as t,o,c as s,a2 as a}from"./chunks/framework.YKbyQ3zk.js";const u=JSON.parse('{"title":"The evo-auth command line","description":"","frontmatter":{},"headers":[],"relativePath":"command-line.md","filePath":"command-line.md"}'),d={name:"command-line.md"};function n(i,e,c,r,l,h){return o(),s("div",null,[...e[0]||(e[0]=[a(`<h1 id="the-evo-auth-command-line" tabindex="-1">The <code>evo-auth</code> command line <a class="header-anchor" href="#the-evo-auth-command-line" aria-label="Permalink to &quot;The \`evo-auth\` command line&quot;">​</a></h1><p>This page is for the developer or operator who sets up, checks and rotates keys. The command is the <code>bin</code> entry of <code>@evo-auth/core</code>: after you install the package, run it with <code>pnpm exec evo-auth</code>, or with npm <code>npx @evo-auth/core</code>. Never give npx the bare name <code>evo-auth</code>: where the package is not installed, npx fetches whoever owns that unscoped name on npm and runs it with your env file. It uses only Node&#39;s own modules and needs Node <code>^22.18.0 || &gt;=23.6.0</code>.</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes evo-light evo-dark vp-code" tabindex="0"><code><span class="line"><span>evo-auth &lt;command&gt; [options]</span></span>
<span class="line"><span>evo-auth --help</span></span></code></pre></div><table tabindex="0"><thead><tr><th>Command</th><th>What it does</th></tr></thead><tbody><tr><td><code>init</code></td><td>Writes <code>evo-auth.config.ts</code> and <code>.env.example</code>, writes a new <code>EVO_AUTH_SECRET</code> and a new <code>EVO_AUTH_PASSWORD_PEPPER</code> to the env file, and prints the command that installs the packages. With <code>--server</code> it also writes the server options file. With <code>--stack</code> it writes a working starting point for one of three stacks instead.</td></tr><tr><td><code>keys generate</code></td><td>Makes a signing key and writes <code>EVO_AUTH_SIGNING_KEY</code> and <code>EVO_AUTH_PUBLIC_KEYS</code> to the env file.</td></tr><tr><td><code>keys rotate</code></td><td>Stages a new signing key. Signing does not change.</td></tr><tr><td><code>keys activate &lt;kid&gt;</code></td><td>Moves signing to the staged key, after you type <code>yes</code>. Also the rollback.</td></tr><tr><td><code>check</code></td><td>Checks the config, the environment and the keys, compares the public key sets, and prints what to register with each provider.</td></tr></tbody></table><p>There is no ban command in <code>evo-auth</code>. On Convex, banning is a function you write on your own server: see <a href="./convex.html#banning-a-user">the Convex guide</a>. On a server project, use <a href="#evo-auth-server"><code>evo-auth-server users ban</code></a>.</p><p><strong>Exit codes:</strong> <code>0</code> done, <code>1</code> refused or failed, <code>2</code> unknown command or option. A usage error prints the reason and the usage text. A refusal prints a message that names files, variables and options, never values.</p><h2 id="what-the-key-file-is" tabindex="-1">What the key file is <a class="header-anchor" href="#what-the-key-file-is" aria-label="Permalink to &quot;What the key file is&quot;">​</a></h2><p><code>init</code> and the <code>keys</code> commands write to one <strong>env file</strong>, <code>.env.local</code> by default; <code>--file &lt;file&gt;</code> names another. It holds the master secret, the signing key, the public keys and a staged key. These rules protect it:</p><ul><li>It is written only if git confirms the file is ignored. If git cannot say so, or the file is tracked, the command refuses and changes nothing. The project must be a git repository whose ignore rules cover the file.</li><li>It is never written through a symbolic link, and an existing key is never replaced.</li><li>It is created with mode <code>0600</code>: read and write for its owner only. <strong>On Windows the mode restricts nothing.</strong> The file gets its folder&#39;s permissions, so keep the project in a folder only your account can read.</li><li>It is replaced whole, through a temporary file in the same folder and a rename. An interrupted write can leave that temporary file behind, holding a key. Delete it.</li><li>No command prints a secret or key value.</li></ul><p>Name the file with <code>--file</code>, not with Node&#39;s <code>--env-file</code>. Node loads a file named by <code>--env-file</code> before <code>evo-auth</code> runs, then <code>evo-auth</code> refuses the option.</p><h2 id="evo-auth-init" tabindex="-1"><code>evo-auth init</code> <a class="header-anchor" href="#evo-auth-init" aria-label="Permalink to &quot;\`evo-auth init\`&quot;">​</a></h2><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes evo-light evo-dark vp-code" tabindex="0"><code><span class="line"><span>evo-auth init [--from &lt;where&gt;] [--file &lt;file&gt;] [--hub &lt;url&gt;] [--server]</span></span>
<span class="line"><span>evo-auth init --stack &lt;stack&gt; [--from &lt;where&gt;]</span></span></code></pre></div><ul><li><p><code>--stack &lt;stack&gt;</code>: write a starting point that signs in with no OAuth app and no mail account, for <code>tanstack-server</code>, <code>tanstack-convex</code> or <code>nextjs-server</code>. See <a href="#init---stack"><code>init --stack</code></a> below. It cannot be combined with <code>--file</code>, <code>--hub</code>, <code>--server</code> or <code>--convex</code>.</p></li><li><p><code>--from &lt;where&gt;</code>: install from the release tarballs instead of the registry. An <code>http</code> or <code>https</code> URL prefix (no user name, password, query or fragment), or a folder.</p></li><li><p><code>--file &lt;file&gt;</code>: the env file for the master secret. The default is <code>.env.local</code>.</p></li><li><p><code>--hub &lt;url&gt;</code>: <code>Sign in through the shared sign-in server at &lt;url&gt;, its publicUrl: the config lists evoHub({ url }) instead of github(), and .env.example has no provider variable.</code> <code>&lt;url&gt;</code> is the server&#39;s own <code>publicUrl</code>: an <code>https</code> URL, or <code>http</code> on a loopback host (<code>localhost</code>, <code>127.0.0.0/8</code> or <code>[::1]</code>) for development, made of its origin followed by its <code>basePath</code>, such as <code>https://auth.example.com/auth</code>. It must have that path, with no trailing slash, no user name, password, query or fragment, and be written as a URL parser writes it back (lower-case scheme and host, no default port, no <code>.</code> or <code>..</code> segment). See <a href="./providers.html#evohub-the-shared-sign-in-server">evoHub()</a>.</p></li><li><p><code>--server</code>: a project that runs <code>@evo-auth/server</code>. It also writes <code>evo-auth.server.mjs</code>, the options file every <code>evo-auth-server</code> command reads (see <a href="#evo-auth-server"><code>evo-auth-server</code></a>), and the install command it prints is for the server package. It cannot be combined with <code>--convex</code>, which a server project has no use for. An existing <code>evo-auth.server.mjs</code> is refused like the other files.</p></li></ul><p>It checks everything first, and refuses, changing nothing, when:</p><ul><li><code>evo-auth.config.ts</code> or <code>.env.example</code> already exists. It never overwrites a file.</li><li>The env file already assigns <code>EVO_AUTH_SECRET</code>. Remove that line to generate a new one.</li><li>Git does not confirm the env file is ignored.</li><li><code>--from</code> is neither a URL prefix nor an existing folder.</li><li><code>--hub</code> is not a <code>publicUrl</code> of the form above. The refusal says which rule it breaks and does not repeat the URL.</li></ul><p>Otherwise it writes:</p><ul><li><code>EVO_AUTH_SECRET</code> to the env file: 32 random bytes as base64url.</li><li><code>EVO_AUTH_PASSWORD_PEPPER</code> to the env file: 32 random bytes as base64url, made separately from the secret. It is the pepper of password hashes, which <code>emailAuth.password</code> needs, and it is written now so that turning passwords on later needs no step. A pepper already in the file is kept, never replaced, because replacing it makes every user reset their password (see <a href="./email-password.html#the-pepper">Email and password</a>).</li><li><code>EVO_AUTH_SECOND_FACTOR_KEY</code> to the env file: 32 random bytes as base64url, made separately from the secret and the pepper. It is the key two-step sign-in seals authenticator secrets and backup codes under, which <code>secondFactor.enabled</code> needs, and it is written now so that turning two-step sign-in on later needs no step. A key already in the file is kept, never replaced by <code>init</code>: a key is replaced by the steps in <a href="./rotating-secrets.html#replacing-evo_auth_second_factor_key">Rotating secrets</a>, with a previous key and a reseal, so nobody sets up again.</li><li><code>evo-auth.config.ts</code>: a skeleton that default-exports <code>validateConfig({ publicUrl: &quot;http://localhost:3000/auth&quot;, cookies: { devMode: true }, providers: [github()] })</code>. It is valid for local development. It enables GitHub, so the auth side refuses to start until the GitHub client id and secret are set. For production, set an https <code>publicUrl</code> and remove <code>cookies.devMode</code>. With <code>--hub &lt;url&gt;</code> the skeleton lists <code>providers: [evoHub({ url: &quot;&lt;url&gt;&quot; })]</code> instead of <code>github()</code>, and it needs no provider variable: this app&#39;s origin is its client id, and it has no client secret. The skeleton&#39;s comment names this app&#39;s callback address, <code>http://localhost:3000/auth/evo/callback</code>, and <code>evo-auth check</code> then prints the exact callback address to add to the server&#39;s <code>hub.allowedClients</code> and says that no client secret is needed.</li><li><code>.env.example</code>: every <code>EVO_AUTH_*</code> name from the config definition. The required ones are empty assignments. Each provider of the skeleton gets both of its variables, <code>EVO_AUTH_{ID}_CLIENT_ID</code> and <code>EVO_AUTH_{ID}_CLIENT_SECRET</code> with its id in upper case, as empty assignments: <code>EVO_AUTH_GITHUB_CLIENT_ID</code> and <code>EVO_AUTH_GITHUB_CLIENT_SECRET</code> for <code>github()</code>. The optional ones, such as <code>EVO_AUTH_PROXY_SECRET</code>, <code>EVO_AUTH_PASSWORD_PEPPER</code> and <code>EVO_AUTH_SECOND_FACTOR_KEY</code>, are commented out, so a copied template with its optional lines untouched still starts: a variable that is set but empty is refused. <code>EVO_AUTH_STAGED_SIGNING_KEY</code> is left out, because the command line writes it. With <code>--hub &lt;url&gt;</code> no provider variable is written: the <code>evoHub()</code> provider has none, so the file holds only the <code>EVO_AUTH_*</code> names that are not a provider&#39;s. If you add a provider to the config, add its two variables yourself; see <a href="./providers.html">Sign-in providers</a>.</li></ul><p>It then prints the install command, for the package manager it was run under (read from <code>npm_config_user_agent</code>, which pnpm, npm, yarn and bun set for the programs they run; <code>npm install</code> when it is not set):</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes evo-light evo-dark vp-code" tabindex="0"><code><span class="line"><span>pnpm add @evo-auth/core@0.1.1 @evo-auth/convex@0.1.1 @evo-auth/react@0.1.1</span></span></code></pre></div><p>With <code>--from</code> it prints <code>npm install</code> of the release tarballs instead: with <code>--from https://example.com/releases/</code> the three URLs, with a folder the three file paths in it. Nothing is fetched. A URL install works only if the tarballs are published at that address.</p><h3 id="init---stack" tabindex="-1"><code>init --stack</code> <a class="header-anchor" href="#init---stack" aria-label="Permalink to &quot;\`init --stack\`&quot;">​</a></h3><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes evo-light evo-dark vp-code" tabindex="0"><code><span class="line"><span>pnpm exec evo-auth init --stack tanstack-server</span></span></code></pre></div><p>Run it in the app&#39;s folder after creating the app and installing the packages. The folder must be a git repository whose ignore rules cover <code>.env.local</code>. It checks everything first, and refuses, changing nothing, when:</p><ul><li>any file it would write already exists. It never overwrites a file, and never edits one: <code>package.json</code> is never touched.</li><li>git is missing, the folder is not in a git repository, or git does not confirm <code>.env.local</code> is ignored.</li><li><code>.env.local</code> already assigns <code>EVO_AUTH_SECRET</code>, <code>EVO_AUTH_SIGNING_KEY</code>, <code>EVO_AUTH_PUBLIC_KEYS</code>, <code>EVO_AUTH_STAGED_SIGNING_KEY</code> or <code>EVO_AUTH_PROXY_SECRET</code>. It never replaces a secret or a key. Its other lines, such as the ones <code>npx convex dev</code> writes, are kept.</li><li>for <code>tanstack-convex</code>, the <code>convex</code> package is not installed.</li></ul><p>Otherwise it writes <code>EVO_AUTH_SECRET</code>, <code>EVO_AUTH_SIGNING_KEY</code>, <code>EVO_AUTH_PUBLIC_KEYS</code>, <code>EVO_AUTH_PROXY_SECRET</code>, <code>EVO_AUTH_PASSWORD_PEPPER</code> and <code>EVO_AUTH_SECOND_FACTOR_KEY</code> to <code>.env.local</code> (a pepper or second-factor key already there is kept), and nowhere else: no file it writes holds a secret, and nothing it prints shows one. Each process that needs them loads <code>.env.local</code> itself with <code>process.loadEnvFile</code>, in a file <code>init</code> writes, keeping any variable already set in the environment.</p><p>Every stack gets <code>evo-auth.config.ts</code>: <code>publicUrl</code> <code>http://localhost:3000/auth</code>, <code>cookies.devMode</code>, no provider, <code>emailAuth: { password: true, signUp: true }</code> and <code>email.sender: devConsoleSender()</code>, which prints each code in the auth side&#39;s terminal (see <a href="./email.html">Email</a>). Then:</p><table tabindex="0"><thead><tr><th>Stack</th><th>It also writes</th></tr></thead><tbody><tr><td><code>tanstack-server</code></td><td><code>evo-auth.server.mjs</code> (loads <code>.env.local</code>, listens on <code>127.0.0.1:3001</code>), <code>src/lib/evo-auth.server.ts</code>, <code>src/routes/auth/$.ts</code>, <code>src/middleware/evo-auth.ts</code>, <code>src/components/evo-auth-root.tsx</code>, <code>src/routes/sign-in.tsx</code>, <code>src/routes/sign-up.tsx</code>, and <code>src/start.ts</code> if the app has none</td></tr><tr><td><code>tanstack-convex</code></td><td><code>convex/convex.config.ts</code>, <code>convex/auth.config.ts</code>, <code>convex/http.ts</code>, <code>convex/auth.ts</code>, and the same <code>src/</code> files with <code>ConvexProviderWithEvoAuth</code> in the root component. It then sets the six variables on the Convex deployment, each value on standard input</td></tr><tr><td><code>nextjs-server</code></td><td><code>evo-auth.server.mjs</code>, <code>lib/auth.ts</code>, <code>proxy.ts</code>, <code>app/auth/[...path]/route.ts</code>, <code>app/sign-in/page.tsx</code>, <code>app/sign-up/page.tsx</code> (under <code>src/</code> when the app keeps <code>app/</code> there), and <code>server.mjs</code>, the custom server that loads <code>.env.local</code> and sets <code>x-forwarded-for</code> to each connection&#39;s address</td></tr></tbody></table><p>It prints each edit to an existing file for you to make, with the file&#39;s name: the three edits to the root route or layout, the line for <code>src/start.ts</code> when that file exists, and the <code>.gitignore</code> line for the server&#39;s database. Last it prints the install command and the commands that start it.</p><h2 id="evo-auth-keys-generate" tabindex="-1"><code>evo-auth keys generate</code> <a class="header-anchor" href="#evo-auth-keys-generate" aria-label="Permalink to &quot;\`evo-auth keys generate\`&quot;">​</a></h2><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes evo-light evo-dark vp-code" tabindex="0"><code><span class="line"><span>evo-auth keys generate [--file &lt;file&gt;] [--convex]</span></span></code></pre></div><p>Makes a P-256 signing key and writes <code>EVO_AUTH_SIGNING_KEY</code> (the private key) and <code>EVO_AUTH_PUBLIC_KEYS</code> (the public set) to the env file. It refuses when the file already holds <code>EVO_AUTH_SIGNING_KEY</code>, <code>EVO_AUTH_PUBLIC_KEYS</code> or <code>EVO_AUTH_STAGED_SIGNING_KEY</code>. Use <code>keys rotate</code> to change keys.</p><h2 id="evo-auth-keys-rotate" tabindex="-1"><code>evo-auth keys rotate</code> <a class="header-anchor" href="#evo-auth-keys-rotate" aria-label="Permalink to &quot;\`evo-auth keys rotate\`&quot;">​</a></h2><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes evo-light evo-dark vp-code" tabindex="0"><code><span class="line"><span>evo-auth keys rotate [--file &lt;file&gt;] [--convex]</span></span></code></pre></div><p>Stages a new key. It adds the new public key to <code>EVO_AUTH_PUBLIC_KEYS</code> and keeps the new private key as <code>EVO_AUTH_STAGED_SIGNING_KEY</code>. <code>EVO_AUTH_SIGNING_KEY</code> does not change, so signing does not move until <code>keys activate</code>. It prints the id of the staged key (its <code>kid</code>, the RFC 7638 thumbprint of its public part) in its last line:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes evo-light evo-dark vp-code" tabindex="0"><code><span class="line"><span>Next: once every verifier has the new EVO_AUTH_PUBLIC_KEYS, run evo-auth keys activate &lt;staged kid&gt;.</span></span></code></pre></div><p>It refuses when the file holds no signing key, when the public set cannot be read, and when the file already holds a staged key that is waiting to be activated (it names that key&#39;s <code>kid</code>: activate it, or remove the line). If the staged key is a kept rollback key from an earlier activation, <code>keys rotate</code> replaces it and says so, because that closes the rollback window early:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes evo-light evo-dark vp-code" tabindex="0"><code><span class="line"><span>It replaces the kept rollback key kid &lt;previous kid&gt; in EVO_AUTH_STAGED_SIGNING_KEY, which closes the rollback window early: evo-auth keys activate &lt;previous kid&gt; no longer rolls back. Kid &lt;previous kid&gt; stays in EVO_AUTH_PUBLIC_KEYS until &lt;time&gt;.</span></span></code></pre></div><h2 id="evo-auth-keys-activate" tabindex="-1"><code>evo-auth keys activate</code> <a class="header-anchor" href="#evo-auth-keys-activate" aria-label="Permalink to &quot;\`evo-auth keys activate\`&quot;">​</a></h2><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes evo-light evo-dark vp-code" tabindex="0"><code><span class="line"><span>evo-auth keys activate &lt;kid&gt; [--file &lt;file&gt;] [--convex]</span></span></code></pre></div><p>Switches signing to the staged key, once every verifier has the new public set. The <code>kid</code> is required and must equal the staged key&#39;s. A bare <code>keys activate</code> is refused with exit code <code>2</code>. When a key is staged, the message names its <code>kid</code>; when nothing is staged, it says the file holds no staged key and to run <code>evo-auth keys rotate</code> first. A <code>kid</code> that is not the staged key&#39;s is refused with exit code <code>1</code> and &quot;Nothing was written.&quot; So a rollback never happens by accident: the key in <code>EVO_AUTH_STAGED_SIGNING_KEY</code> is the one you name.</p><p>It then:</p><ol><li>Shows the comparison <code>check</code> makes of the public sets and asks <code>Make kid &lt;staged kid&gt; the signing key and retire kid &lt;previous kid&gt;? Type yes to confirm:</code>. Any answer but <code>yes</code>, or no answer, changes nothing (<code>Not confirmed. Nothing was written.</code>, exit code <code>1</code>). It reads the answer from standard input.</li><li>Writes the staged key as <code>EVO_AUTH_SIGNING_KEY</code>, sets the retiring key&#39;s <code>removeAfter</code> to now plus <code>accessToken.lifetimeSeconds</code>, <code>clockSkewSeconds</code> and 300 seconds, and moves the previous signing key into <code>EVO_AUTH_STAGED_SIGNING_KEY</code>. The line is not removed.</li><li>Prints the rollback command and when its window closes:</li></ol><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes evo-light evo-dark vp-code" tabindex="0"><code><span class="line"><span>Activated kid &lt;staged kid&gt; in .env.local (mode 0600; on Windows the mode does not restrict access): it is now EVO_AUTH_SIGNING_KEY. The previous signing key, kid &lt;previous kid&gt;, is kept as EVO_AUTH_STAGED_SIGNING_KEY for a rollback and stays in EVO_AUTH_PUBLIC_KEYS until &lt;time&gt;.</span></span>
<span class="line"><span>Set EVO_AUTH_SIGNING_KEY and EVO_AUTH_PUBLIC_KEYS from .env.local where your deployments read them; values are not printed.</span></span>
<span class="line"><span>To roll back: evo-auth keys activate &lt;previous kid&gt; (available until &lt;time&gt;)</span></span></code></pre></div><p><code>&lt;time&gt;</code> is an ISO 8601 date and time in this machine&#39;s time zone, with its offset, for example <code>2026-11-12T14:07:12+00:00</code>.</p><p><strong>There is no flag to skip a check and no flag for a redeploy.</strong> Without <code>--convex</code>, <code>activate</code> compares the public sets <code>check</code> compares and nothing about Convex. Set the new variables where your deployments read them, as the second line says.</p><h3 id="--convex" tabindex="-1"><code>--convex</code> <a class="header-anchor" href="#--convex" aria-label="Permalink to &quot;\`--convex\`&quot;">​</a></h3><p>With <code>--convex</code>, <code>activate</code> is refused, before it asks, until the Convex deployment&#39;s <code>EVO_AUTH_PUBLIC_KEYS</code> lists the staged key. Set that variable first (<code>evo-auth keys rotate --convex</code> does it) and run <code>evo-auth check --convex</code> until it says the deployment lists the staged <code>kid</code>. A key added to the variable is picked up with no push on the local backend; on Convex cloud that is unverified, so push after setting the variable and before <code>keys activate</code> (see <a href="./convex.html#rotating-the-signing-keys">the Convex guide</a>).</p><p>After the file is written, <code>--convex</code> sets <code>EVO_AUTH_SIGNING_KEY</code> and <code>EVO_AUTH_PUBLIC_KEYS</code> on the deployment, each value on standard input and shown as <code>[redacted]</code> in the Convex output. The staged private key never goes to Convex, so a rollback sets the same two variables.</p><h3 id="rolling-back" tabindex="-1">Rolling back <a class="header-anchor" href="#rolling-back" aria-label="Permalink to &quot;Rolling back&quot;">​</a></h3><p>Run the <code>To roll back:</code> line it printed. It works until the retiring key&#39;s <code>removeAfter</code>. After that <code>activate</code> refuses that <code>kid</code> (<code>can no longer be activated: its rollback window closed</code>), and the next <code>keys rotate</code> removes the key and stages a new one. <code>check</code> reports a staged key whose <code>removeAfter</code> has passed, or whose <code>kid</code> is not in the public set, and tells you to remove it.</p><p>A rollback is itself an activation: it asks you to confirm, keeps the key it replaces as the staged key, and prints a new <code>To roll back:</code> line.</p><h2 id="evo-auth-check" tabindex="-1"><code>evo-auth check</code> <a class="header-anchor" href="#evo-auth-check" aria-label="Permalink to &quot;\`evo-auth check\`&quot;">​</a></h2><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes evo-light evo-dark vp-code" tabindex="0"><code><span class="line"><span>evo-auth check [--file &lt;file&gt;] [--convex]</span></span></code></pre></div><p>Checks <code>evo-auth.config.ts</code> in the current folder and the env file (<code>.env.local</code>, or <code>--file</code>). It reads the env file only, not the running process&#39;s environment, so its report describes the file your deployments are set from. It prints no value.</p><p>The report has five sections, and a sixth when the config has an <code>oidc()</code> provider. A passing run:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes evo-light evo-dark vp-code" tabindex="0"><code><span class="line"><span>evo-auth check: evo-auth.config.ts and .env.local. No value is printed.</span></span>
<span class="line"><span></span></span>
<span class="line"><span>Config</span></span>
<span class="line"><span>  evo-auth.config.ts is valid.</span></span>
<span class="line"><span></span></span>
<span class="line"><span>Environment (.env.local)</span></span>
<span class="line"><span>  Every variable the auth deployment reads is set and well formed.</span></span>
<span class="line"><span></span></span>
<span class="line"><span>Keys</span></span>
<span class="line"><span>  EVO_AUTH_PUBLIC_KEYS lists kid &lt;active kid&gt; (active).</span></span>
<span class="line"><span></span></span>
<span class="line"><span>Public key sets</span></span>
<span class="line"><span>  the JWKS at http://localhost:3000/auth/.well-known/jwks.json: the same keys as .env.local.</span></span>
<span class="line"><span></span></span>
<span class="line"><span>Deployment</span></span>
<span class="line"><span>  Register this callback URL with GitHub: http://localhost:3000/auth/github/callback</span></span>
<span class="line"><span>  WARNING: wildcard redirect matching must be off on the GitHub OAuth app. Register exactly the callback URL above.</span></span>
<span class="line"><span>  Client-address mode: connection_address</span></span>
<span class="line"><span>  Development cookie mode: on</span></span>
<span class="line"><span></span></span>
<span class="line"><span>check found no problems.</span></span></code></pre></div><table tabindex="0"><thead><tr><th>Section</th><th>What it checks</th></tr></thead><tbody><tr><td>Config</td><td>The config loads and is valid. A setting that is missing or breaks a rule is named.</td></tr><tr><td>Environment</td><td>Every variable the auth deployment reads is set and well formed. A master secret or proxy secret that is not base64url or decodes to under 32 bytes, a proxy secret equal to the master secret, a malformed key, and a configured provider whose client id and secret are not set are each named. A provider&#39;s two variables are named by the rule <code>EVO_AUTH_{ID}_CLIENT_ID</code> and <code>EVO_AUTH_{ID}_CLIENT_SECRET</code> from its id, or for <code>apple()</code> <code>EVO_AUTH_APPLE_CLIENT_ID</code> and <code>EVO_AUTH_APPLE_PRIVATE_KEY</code>: both missing are named together, and one missing or empty is named alone. A config with <code>emailAuth.password</code> on and no <code>EVO_AUTH_PASSWORD_PEPPER</code> is a problem, and so is one with <code>secondFactor.enabled</code> on and no <code>EVO_AUTH_SECOND_FACTOR_KEY</code>. With <code>--convex</code>, a missing <code>EVO_AUTH_PROXY_SECRET</code> outside the development cookie mode is a problem. While the file sets <code>EVO_AUTH_SECOND_FACTOR_KEY_PREVIOUS</code>, it prints <code>WARNING: EVO_AUTH_SECOND_FACTOR_KEY_PREVIOUS is set: the second-factor key is being replaced.</code>, followed by what to do; a warning, not a problem.</td></tr><tr><td>Keys</td><td>The keys import, the active key&#39;s thumbprint is in the public set, and each key in <code>EVO_AUTH_PUBLIC_KEYS</code> is listed by <code>kid</code> with its role: <code>active</code>, <code>staged</code>, or <code>retiring, removeAfter &lt;time&gt;</code>. A key past its <code>removeAfter</code>, and a staged key that is not in the public set or whose rollback window has closed, are problems.</td></tr><tr><td>Public key sets</td><td>The local set is compared with the JWKS published at <code>{publicUrl}/.well-known/jwks.json</code> (10-second timeout). With <code>--convex</code> it is also compared with the Convex deployment&#39;s <code>EVO_AUTH_PUBLIC_KEYS</code>. A difference, or a set that cannot be read, is a problem. With a staged key, it says whether each set lists it.</td></tr><tr><td>OpenID Connect discovery</td><td>Only with an <code>oidc()</code> provider. Each one&#39;s discovery document, <code>{issuer}/.well-known/openid-configuration</code>, read with no redirect followed and a 10-second timeout, is compared with the config: an <code>issuer</code>, <code>authorization_endpoint</code>, <code>token_endpoint</code>, <code>jwks_uri</code> or (when the config sets one) <code>userinfo_endpoint</code> that differs or is missing is a problem naming the member and the config&#39;s option, as is a <code>token_endpoint_auth_methods_supported</code> list without the method the provider uses: <code>client_secret_basic</code> for <code>oidc()</code> and most presets, <code>client_secret_post</code> for a provider with <code>tokenAuth: &quot;post&quot;</code>, and <code>none</code> for <code>evoHub()</code>. A document without that list passes for <code>client_secret_basic</code>, and fails for the others except <code>linkedin()</code>, which is accepted with a line saying why. A document that cannot be read is a problem. Nothing the document says is printed.</td></tr><tr><td>Deployment</td><td>On a shared sign-in server, one warning for each wildcard in <code>hub.allowedClients</code>, naming the domain it covers and saying to use a wildcard only for a domain you own: on a shared hosting name such as <code>my-hub.vercel.app</code>, <code>https://*.vercel.app</code> would let every app on that host sign in through the hub. The callback URL to register with each provider, <code>{publicUrl}/{id}/callback</code>, and for GitHub the wildcard warning; the client-address mode (<code>proxy</code>, <code>connection_address</code>, or <code>convex_dev_metadata</code>); and whether the development cookie mode is on.</td></tr></tbody></table><p>Every problem is one line starting <code>problem:</code> and is counted. Any problem makes the exit code <code>1</code>; the last line is <code>check found &lt;n&gt; problem(s).</code> A usage error exits <code>2</code>. A line starting <code>WARNING:</code> is not a problem and does not change the exit code.</p><p>The JWKS comes from your running app, so <code>check</code> finds one problem until the app serves it. Before that, the Public key sets section says:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes evo-light evo-dark vp-code" tabindex="0"><code><span class="line"><span>  problem: the JWKS at http://localhost:3000/auth/.well-known/jwks.json: could not be reached</span></span></code></pre></div><p>The other sections are still worth reading.</p><h3 id="--convex-1" tabindex="-1"><code>--convex</code> <a class="header-anchor" href="#--convex-1" aria-label="Permalink to &quot;\`--convex\`&quot;">​</a></h3><p><code>--convex</code> also compares the keys with the Convex deployment&#39;s <code>EVO_AUTH_PUBLIC_KEYS</code>, read through the project&#39;s own Convex command line (the <code>convex</code> package must be installed in the project). It then starts with <code>On Convex the order is: set the variables, push, then run evo-auth check.</code></p><p>Loading <code>evo-auth.config.ts</code> relies on Node&#39;s built-in TypeScript type stripping, so <code>evo-auth</code> needs Node <code>^22.18.0 || &gt;=23.6.0</code>, the <code>engines</code> range of <code>@evo-auth/core</code>.</p><h2 id="evo-auth-server" tabindex="-1"><code>evo-auth-server</code> <a class="header-anchor" href="#evo-auth-server" aria-label="Permalink to &quot;\`evo-auth-server\`&quot;">​</a></h2><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes evo-light evo-dark vp-code" tabindex="0"><code><span class="line"><span>evo-auth-server &lt;command&gt; [--options &lt;file&gt;]</span></span>
<span class="line"><span>evo-auth-server --help</span></span></code></pre></div><p><code>evo-auth-server</code> is the <code>bin</code> entry of <code>@evo-auth/server</code>, the sign-in server that keeps its data in one SQLite file. Run it with <code>pnpm exec evo-auth-server</code> in your project folder, or with npm <code>npx @evo-auth/server</code>; never give npx the bare name <code>evo-auth-server</code>, for the same reason.</p><p><strong>The options file.</strong> Every command reads <code>evo-auth.server.mjs</code> in the folder you run it from; <code>--options &lt;file&gt;</code> names another. <code>evo-auth init --server</code> writes one. It is a JavaScript module whose default export holds <code>config</code> (what <code>validateConfig</code> returns), <code>database.path</code> (relative to the options file&#39;s folder), <code>listen</code> (<code>{ host?, port, public? }</code>) and, if you use them, <code>trustedProxies</code>, <code>webhooks</code> (a list of <code>{ id, url }</code>) and <code>hooks</code>. Secrets are never in it: they are <code>EVO_AUTH_*</code> environment variables, including <code>EVO_AUTH_WEBHOOK_&lt;ID&gt;_SECRET</code> for each webhook endpoint.</p><table tabindex="0"><thead><tr><th>Command</th><th>What it does</th></tr></thead><tbody><tr><td><code>start</code></td><td>Opens the database file (creating it if it is missing), takes the runner lease, runs the background work and listens. It prints one line saying where. On SIGTERM or SIGINT it finishes the requests in progress, releases the lease and exits <code>0</code>. It refuses, exit <code>1</code>, on a bad option, a missing secret, a lease held by another server or a port in use.</td></tr><tr><td><code>migrate</code></td><td>Brings the database file to the schema version this release reads. An older file is first copied beside itself as <code>&lt;file&gt;.pre-v&lt;N&gt;-&lt;timestamp&gt;.bak</code>; a newer file is refused and changed in no way.</td></tr><tr><td><code>backup &lt;dest&gt;</code></td><td>Writes a consistent copy of the database to <code>&lt;dest&gt;</code>, a file that does not exist yet. It is safe while the server runs.</td></tr><tr><td><code>check</code></td><td>Reads the database and the environment and changes nothing. It prints the file&#39;s schema version beside the version this release reads, the runner lease (free, or held until a time), each webhook endpoint&#39;s URL, and whether each secret the server needs is present, by variable name and never by value. It prints <code>Organisation roles: fingerprint &lt;value&gt;</code>, the SHA-256 of <code>organizations.roles</code> as canonical JSON (keys sorted, lists in their order) in base64url: the same roles give the same fingerprint, so two configs can be compared by it. It names each role that memberships in the file hold and <code>organizations.roles</code> no longer lists, with how many hold it: those memberships have no permissions. It exits <code>1</code> if anything is missing or wrong, such a role included. It reports <code>EVO_AUTH_SECOND_FACTOR_KEY</code> present, or unused while <code>secondFactor.enabled</code> is off. While <code>secondFactor.enabled</code> is off and users still have a confirmed second factor, it prints <code>WARNING: &lt;n&gt; users have a second factor, which is not being enforced while secondFactor.enabled is off.</code> (<code>&lt;n&gt; user has</code> for one). That is a warning, not a problem: <code>check</code> still exits <code>0</code>, because turning the setting off can be deliberate. While <code>usernames.enabled</code> is off and users still hold a username, it prints <code>WARNING: &lt;n&gt; users hold a username, which sign nobody in while usernames.enabled is off.</code> (<code>&lt;n&gt; user holds a username, which signs</code> for one). Whatever that setting, when held names are on <code>usernames.reserved</code> or the built-in reserved list, it prints <code>WARNING: &lt;n&gt; held usernames are on the reserved list and stay held, since the list applies to new choices only: &lt;names&gt;.</code> (<code>username is</code> and <code>stays</code> for one), naming them. Both are warnings, not problems. While <code>EVO_AUTH_SECOND_FACTOR_KEY_PREVIOUS</code> is set, it prints <code>WARNING: EVO_AUTH_SECOND_FACTOR_KEY_PREVIOUS is set: the second-factor key is being replaced.</code>, then to run <code>second-factor reseal</code> until it reports 0 and 0 and remove the variable; while it equals the key, the warning says a rotation has started and the key needs a new value. Also a warning, never a value, and the exit code is unchanged; only the reseal counts the rows still under the old key.</td></tr><tr><td><code>users ban &lt;id&gt;</code>, <code>users unban &lt;id&gt;</code>, <code>users delete &lt;id&gt;</code></td><td>Does what the admin API does for that user, in the database file. A ban writes its <code>user.updated</code> webhook rows, and the app&#39;s <code>hooks</code> run. It works while the server runs and while it is stopped. An id that no user has is refused.</td></tr><tr><td><code>users second-factor remove &lt;id&gt;</code></td><td>Removes the user&#39;s second factor, for someone who has lost their authenticator and backup codes. Every session of the user ends, and <code>second_factor_removed</code> is recorded with no actor. While <code>email.sender</code> is set and the user has an email account, the administrator&#39;s wording of the removal notice is queued, and the running server sends it. A user that does not exist or has no second factor is refused. It works while the server runs and while it is stopped, needs no secret, and writes no webhook row: the factor is not in the user payload. See <a href="./second-factor.html#recovery">Two-step sign-in</a>.</td></tr><tr><td><code>second-factor reseal</code></td><td>While <code>EVO_AUTH_SECOND_FACTOR_KEY</code> is being replaced, seals again under the current key every second factor still under <code>EVO_AUTH_SECOND_FACTOR_KEY_PREVIOUS</code>, in pages of 200 rows. It prints <code>Resealed: &lt;n&gt;</code>, <code>Still under the previous key: &lt;m&gt;</code> and <code>Open under neither key: &lt;k&gt;</code>, then the user ids counted in <code>&lt;k&gt;</code>: those were sealed under a third, older key, and each must be removed with <code>users second-factor remove &lt;id&gt;</code>. A row whose backup codes were stored before codes were sealed is printed on its own line, <code>Backup codes in the old format: &lt;n&gt; (the person makes new codes, or the factor is removed)</code>, with its user ids. It exits <code>0</code> when <code>&lt;m&gt;</code>, <code>&lt;k&gt;</code> and <code>&lt;n&gt;</code> are all 0 and <code>1</code> otherwise, so it is run until it exits <code>0</code>. A row someone changed while it was read (a backup code used, an authenticator replaced) is left as it is and counted in <code>&lt;m&gt;</code>. It refuses without <code>EVO_AUTH_SECOND_FACTOR_KEY_PREVIOUS</code>, naming it, and prints counts and user ids only, never a key or a value. It works while the server runs. See <a href="./rotating-secrets.html#the-reseal">Rotating secrets</a>.</td></tr><tr><td><code>webhooks failed</code></td><td>Lists the webhook deliveries that gave up: id, endpoint, event type, when first tried (UTC) and attempts.</td></tr><tr><td><code>webhooks redeliver &lt;id&gt;</code></td><td>Makes a failed delivery due again, with the same id. A delivery that is unknown, or not failed, is refused.</td></tr></tbody></table><p>A user id may start with a hyphen; an id that starts with two hyphens follows a lone <code>--</code>, as in <code>evo-auth-server users ban -- --abc</code>. Only <code>start</code> takes the lease or runs jobs and deliveries. The <code>users</code> and <code>webhooks redeliver</code> commands write their rows and never send them: the running server&#39;s delivery loop and job runner do that. A <code>users</code> command checks each webhook endpoint&#39;s id and URL but needs no webhook secret, because only the running server signs; <code>start</code> and <code>check</code> do read the secrets.</p><p><strong>Exit codes:</strong> <code>0</code> done, <code>1</code> refused or failed (for <code>check</code>, something is missing or wrong), <code>2</code> unknown command or option. No command prints a secret.</p><h2 id="see-also" tabindex="-1">See also <a class="header-anchor" href="#see-also" aria-label="Permalink to &quot;See also&quot;">​</a></h2><ul><li><a href="./rotating-secrets.html">Rotating secrets</a></li><li><a href="./security-model.html#where-secrets-live">Security model</a></li><li><a href="./configuration.html">Configuration</a></li></ul>`,73)])])}const v=t(d,[["render",n]]);export{u as __pageData,v as default};
